Definition iarm2_0_1RB0LD_1LC1RA_0RB1LD_0RB0LC : LRule :=
  mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S0] [] 0 0 []))
          (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [] 0 0 [])) 0 2.
Definition ch_iarm2_0_1RB0LD_1LC1RA_0RB1LD_0RB0LC : list rstep := [RB (SWin 2)].
Lemma ok_iarm2_0_1RB0LD_1LC1RA_0RB1LD_0RB0LC :
