(** The boot, on the ORIGINAL machine and up to [lift]: the member at index
    7, past the last fire of every pinned instruction. *)
Lemma bootq_1RB0LD_1LC1RA_0RB1LD_0RB0LC :
  stepn tm_1RB0LD_1LC1RA_0RB1LD_0RB0LC 7 InitES = Some (lift (fam_cfg FAM ([2], 0, 0))).
Proof.
  assert (H : match csteps tm_1RB0LD_1LC1RA_0RB1LD_0RB0LC 7 c0 with
              | Some c => ceqb c (fam_cfg FAM ([2], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm_1RB0LD_1LC1RA_0RB1LD_0RB0LC 7 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** a pinned instruction fired before the boot: the quasihalt witness *)
Lemma wit_1RB0LD_1LC1RA_0RB1LD_0RB0LC :
  existsb (fun tg => cfires tm_1RB0LD_1LC1RA_0RB1LD_0RB0LC c0 7 tg) pins_1RB0LD_1LC1RA_0RB1LD_0RB0LC = true.
Proof. vm_compute. reflexivity. Qed.

Lemma bnd_1RB0LD_1LC1RA_0RB1LD_0RB0LC : (7 <=? 32779478) = true.
Proof. apply bound_tr_leb; vm_cast_no_check (eq_refl true). Qed.

(** The machine-level theorem, on the QUASIHALTING side: the board above
    runs on the machine wrapped at the pins from the boot member on, and
    [LadderCheckQHTr.boardph_qhtr] closes it. *)
Theorem qhtr_1RB0LD_1LC1RA_0RB1LD_0RB0LC :
  NonHalt tm_1RB0LD_1LC1RA_0RB1LD_0RB0LC /\ QHBoundTr 32779478 tm_1RB0LD_1LC1RA_0RB1LD_0RB0LC /\ QuasiHaltsTr tm_1RB0LD_1LC1RA_0RB1LD_0RB0LC.
Proof.
  eapply (boardphL_qhtr tm_1RB0LD_1LC1RA_0RB1LD_0RB0LC pins_1RB0LD_1LC1RA_0RB1LD_0RB0LC FAM 1
    iarm_1RB0LD_1LC1RA_0RB1LD_0RB0LC 1 1 farm_1RB0LD_1LC1RA_0RB1LD_0RB0LC 1 1 fm1_1RB0LD_1LC1RA_0RB1LD_0RB0LC fm2_1RB0LD_1LC1RA_0RB1LD_0RB0LC padl_1RB0LD_1LC1RA_0RB1LD_0RB0LC padr_1RB0LD_1LC1RA_0RB1LD_0RB0LC
    0 vis_1RB0LD_1LC1RA_0RB1LD_0RB0LC [2] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB0LD_1LC1RA_0RB1LD_0RB0LC.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - lia.
  - exact iarm_sound_1RB0LD_1LC1RA_0RB1LD_0RB0LC.
  - exact iarm_lhs_1RB0LD_1LC1RA_0RB1LD_0RB0LC.
  - exact iarm_rhs_1RB0LD_1LC1RA_0RB1LD_0RB0LC.
  - exact iarm_cb_1RB0LD_1LC1RA_0RB1LD_0RB0LC.
  - lia.
  - lia.
