  stepn tm_1RB0LD_1LC1RA_0RB1LD_1RA0LC 6 InitES = Some (lift (fam_cfg FAM ([2;3], 0, 0))).
Proof.
  assert (H : match csteps tm_1RB0LD_1LC1RA_0RB1LD_1RA0LC 6 c0 with
              | Some c => ceqb c (fam_cfg FAM ([2;3], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm_1RB0LD_1LC1RA_0RB1LD_1RA0LC 6 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

