    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB0RB_1RC1RA_1LD1LC_0RA0LC.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - exact bootq_1RB0RB_1RC1RA_1LD1LC_0RA0LC.
  - exact wit_1RB0RB_1RC1RA_1LD1LC_0RA0LC.
  - exact bnd_1RB0RB_1RC1RA_1LD1LC_0RA0LC.
