(** The machine-level theorem, on the QUASIHALTING side: the board above
    runs on the machine wrapped at the pins from the boot member on, and
    [LadderCheckQHTr.boardph_qhtr] closes it. *)
Theorem qhtr_1RB1LC_0RC1RD_1LA0RD_0LC0RB :
  NonHalt tm_1RB1LC_0RC1RD_1LA0RD_0LC0RB /\ QHBoundTr 32779478 tm_1RB1LC_0RC1RD_1LA0RD_0LC0RB /\ QuasiHaltsTr tm_1RB1LC_0RC1RD_1LA0RD_0LC0RB.
Proof.
  eapply (boardphL_qhtr tm_1RB1LC_0RC1RD_1LA0RD_0LC0RB pins_1RB1LC_0RC1RD_1LA0RD_0LC0RB FAM 1
    iarm_1RB1LC_0RC1RD_1LA0RD_0LC0RB 1 1 farm_1RB1LC_0RC1RD_1LA0RD_0LC0RB 1 1 fm1_1RB1LC_0RC1RD_1LA0RD_0LC0RB fm2_1RB1LC_0RC1RD_1LA0RD_0LC0RB padl_1RB1LC_0RC1RD_1LA0RD_0LC0RB padr_1RB1LC_0RC1RD_1LA0RD_0LC0RB
    0 vis_1RB1LC_0RC1RD_1LA0RD_0LC0RB [2;0] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
