    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB1LC_0RC1RD_1LA0RD_0LC0RB.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - lia.
  - exact iarm_sound_1RB1LC_0RC1RD_1LA0RD_0LC0RB.
  - exact iarm_lhs_1RB1LC_0RC1RD_1LA0RD_0LC0RB.
  - exact iarm_rhs_1RB1LC_0RC1RD_1LA0RD_0LC0RB.
