(** 1RB1LC_1LA1RD_0RD0LA_1RB0LC *)
Definition tm_1RB1LC_1LA1RD_0RD0LA_1RB0LC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB
  | StA, S1 => mk S1 DL StC
  | StB, S0 => mk S1 DL StA
  | StB, S1 => mk S1 DR StD
