Definition fam_1RB1LC_1LA1RD_0RD0LA_1RB0LC : Fam := mkFam 4 [[S1;S0];[S0;S0];[S1;S1];[S0;S1]] [] [[]] Binary 1 [mkFill 1 [] 0 [2] 0] StC S0 false [].
Local Notation FAM := fam_1RB1LC_1LA1RD_0RD0LA_1RB0LC.

(** ** The ladder, as DATA

    0 window rule(s).  [check_ladder] validates rule i against rules
