  mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [] 0 0 []))
          (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S0] [] 0 0 [])) 0 2.
