    exfalso; lia.
  }
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LC_1LA1RD_0RD0LA_1RB0LC | exact ok_iarm1_0_1RB1LC_1LA1RD_0RD0LA_1RB0LC]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LC_1LA1RD_0RD0LA_1RB0LC | exact ok_iarm1_1_1RB1LC_1LA1RD_0RD0LA_1RB0LC]. }
    exfalso; lia.
  }
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LC_1LA1RD_0RD0LA_1RB0LC | exact ok_iarm2_0_1RB1LC_1LA1RD_0RD0LA_1RB0LC]. }
