    [vm_compute].  A wrong chain makes the replay return [None] and this
    file fails to compile.

    The certificate's four PARAMETERS -- the fill law per phase with the
    phase it lands in, the terminator of each phase, the counter's code and
    its step per anchor visit -- arrive as fields of a [LadderFam.Fam]
    value, not as definitions in the kernel (LADDER_PLAN.md 4f).

    Axiom footprint: [functional_extensionality_dep], via [CTape.lift]. *)
Import BoundCheckTr.
Import Arith Lia Bool List.
Import BBB4_Statement CTape.
Import TNF_QH.
Import WTape LapGlueQuiet.
Import LapDecider LapAvoid LadderKernel LadderFam.
Import LadderCheck.
Import BBBT4_Statement.
Import WrapTr LadderCheckTr.
Import LapGlueTr.
Import ClosureTr.
Import TNF_QHTr.
Import LadderCheckQHTr.
Import LadderCheckLiftTr.
Import ListNotations.

Definition mk_1RB1LD_1RC1RC_0LD0RB_1LA0RC (w : Sym) (d : Dir) (n : St) : option Trans :=
  Some (mkTrans w d n).
Local Notation mk := mk_1RB1LD_1RC1RC_0LD0RB_1LA0RC.

(** 1RB1LD_1RC1RC_0LD0RB_1LA0RC *)
Definition tm_1RB1LD_1RC1RC_0LD0RB_1LA0RC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB
  | StA, S1 => mk S1 DL StD
  | StB, S0 => mk S1 DR StC
  | StB, S1 => mk S1 DR StC
  | StC, S0 => mk S0 DL StD
  | StC, S1 => mk S0 DR StB
  | StD, S0 => mk S1 DL StA
  | StD, S1 => mk S0 DR StC
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB1LD_1RC1RC_0LD0RB_1LA0RC : list Instr := [(StB, S0)].
Local Notation tm := (tm_wrap_trs tm_1RB1LD_1RC1RC_0LD0RB_1LA0RC pins_1RB1LD_1RC1RC_0LD0RB_1LA0RC).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB1LD_1RC1RC_0LD0RB_1LA0RC : Fam := mkFam 4 [[S1;S0];[S0;S0];[S1;S1];[S0;S1]] [] [[]] Binary 1 [mkFill 1 [] 0 [2] 0] StC S0 true [].
Local Notation FAM := fam_1RB1LD_1RC1RC_0LD0RB_1LA0RC.

(** ** The ladder, as DATA

    0 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1LD_1RC1RC_0LD0RB_1LA0RC : list (LRule * list rstep) :=
  [].
Local Notation lad := lad_1RB1LD_1RC1RC_0LD0RB_1LA0RC.

Definition rules_1RB1LD_1RC1RC_0LD0RB_1LA0RC : list LRule := map fst lad.
Local Notation rules := rules_1RB1LD_1RC1RC_0LD0RB_1LA0RC.

Lemma ladder_ok_1RB1LD_1RC1RC_0LD0RB_1LA0RC : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1LD_1RC1RC_0LD0RB_1LA0RC : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1LD_1RC1RC_0LD0RB_1LA0RC. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
(** ** What this board establishes

    0 of 0 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 0 of them
    collapse to 7 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 1 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)
Definition iarm0_0_1RB1LD_1RC1RC_0LD0RB_1LA0RC : LRule :=
  mkLRule (mkC StC (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []))
          (mkC StC (mkS [S0;S0] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 2.
Definition ch_iarm0_0_1RB1LD_1RC1RC_0LD0RB_1LA0RC : list rstep := [RB (SWin 2)].
Lemma ok_iarm0_0_1RB1LD_1RC1RC_0LD0RB_1LA0RC :
  check_arm tm false true rules iarm0_0_1RB1LD_1RC1RC_0LD0RB_1LA0RC
            ch_iarm0_0_1RB1LD_1RC1RC_0LD0RB_1LA0RC = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm0_1_1RB1LD_1RC1RC_0LD0RB_1LA0RC : LRule :=
