          (mkC StC (mkS [S1;S0] [S1;S0] 1 0 [S0;S0]) S0 (mkS [] [] 0 0 [])) 4 6.
Definition ch_iarm0_1_1RB1LD_1RC1RC_0LD0RB_1LA0RC : list rstep := [RB (SWin 2);RB (SCycL 2 0);RB (SWin 2);RB (SCycR 2);RB (SWin 2)].
