    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LD_1RC1RC_0LD0RB_1LA0RC | exact ok_iarm0_1_1RB1LD_1RC1RC_0LD0RB_1LA0RC]. }
    exfalso; lia.
  }
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LD_1RC1RC_0LD0RB_1LA0RC | exact ok_iarm1_0_1RB1LD_1RC1RC_0LD0RB_1LA0RC]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LD_1RC1RC_0LD0RB_1LA0RC | exact ok_iarm1_1_1RB1LD_1RC1RC_0LD0RB_1LA0RC]. }
    exfalso; lia.
  }
  destruct d as [|d].
