    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LD_1RC1RC_0LD0RB_1LA0RC | exact ok_iarm2_0_1RB1LD_1RC1RC_0LD0RB_1LA0RC]. }
    destruct r as [|r].
